#!/usr/bin/env bash
# make-shims.sh <dir> [ext...]: write `php` and `php-cgi` shims into <dir>
# that, when run with `-n`, load php's shared extensions from the command line
# (see action.yml). Used by this action and by .github/scripts/linux-ci.Dockerfile.
# Extra extensions (e.g. `pdo_mysql`, which a fixture app may need) are
# injected after the default list, in the order given.
#
# - Only an extension whose .so exists and that php hasn't compiled in is
#   injected: anything else prints a startup warning into every comparison.
# - One the command line loads itself (`-d extension=curl.so`, as
#   ext/curl/tests/oom_curl_multi_exec.phpt does) is not injected again,
#   which would warn "Module already loaded", as a php with it built in
#   (Homebrew's) doesn't.
# - The shims run php with themselves as argv[0], so PHP_BINARY is the shim
#   and a test spawning `PHP_BINARY . getenv('TEST_PHP_EXTRA_ARGS')` (" -n
#   ...") keeps the extensions too.
# - Under -n, session.save_path is reset to upstream's default (see below).
set -euo pipefail

shim_dir="$1"
shift
extdir="$(php-config --extension-dir)"
builtin="$(php -n -m | tr 'A-Z' 'a-z')"
exts=""
for e in bcmath bz2 calendar ctype curl dom exif fileinfo gettext gmp iconv intl \
         mbstring openssl pcntl phar posix session shmop simplexml sockets sodium \
         sysvmsg sysvsem sysvshm tokenizer xml xmlreader xmlwriter zip pdo pdo_sqlite \
         "$@"; do
  case " $exts " in *" $e "*) continue ;; esac
  if ! grep -qx "$e" <<<"$builtin" && [ -f "$extdir/$e.so" ]; then
    exts="$exts $e"
  fi
done
echo "shims inject under -n: -d extension_dir=$extdir, extensions:$exts"
mkdir -p "$shim_dir"
v="$(php -r 'echo PHP_MAJOR_VERSION.".".PHP_MINOR_VERSION;')"
for bin in php php-cgi; do
  # php-cgi: Debian's versioned binary, the same build as php.
  real="$(command -v "$bin$([ "$bin" = php-cgi ] && echo "$v")")"
  self="$shim_dir/$bin"
  cat > "$self" <<EOF
#!/usr/bin/env bash
# Generated by .github/actions/setup-php/make-shims.sh.
for a in "\$@"; do
  if [ "\$a" = "-n" ]; then
    args=("\$@")
    own=" "
    for ((i = 0; i < \${#args[@]}; i++)); do
      case "\${args[i]}" in
        -d) v="\${args[i + 1]:-}" ;;
        -d*) v="\${args[i]#-d}" ;;
        *) continue ;;
      esac
      case "\$v" in
        extension=*) e="\${v#extension=}"; e="\${e##*/}"; e="\${e%.so}"; own="\$own\${e#php_} " ;;
      esac
    done
    # Debian builds in session.save_path=/var/lib/php/sessions, which a
    # non-root user can't open: session gc (1 in 100 session_start calls)
    # then prints a notice. Use upstream's default (the temp dir).
    flags=(-d "extension_dir=$extdir" -d "session.save_path=")
    for e in$exts; do
      case "\$own" in
        *" \$e "*) ;;
        *) flags+=(-d "extension=\$e") ;;
      esac
    done
    exec -a "$self" "$real" "\${flags[@]}" "\$@"
  fi
done
exec -a "$self" "$real" "\$@"
EOF
  chmod +x "$self"
done
